(
    'e1c10000-0000-4000-8000-000000000005', 'english',
    'Search and favorites',
    $kb_a005_en${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Search"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhMagnifyingGlass","weight": "regular","size": 16}},{"type": "text","text": " in the tree panel header opens the search field. Typing filters articles across the knowledge bases expanded on the shelf. Clearing the field or hiding search resets the filter."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Favorites block"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhStar","weight": "regular","size": 16}},{"type": "text","text": " in the panel header shows or hides the Favorites block above the tree list. The block lists every article starred by the current user."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Star an article"}]},{"type": "paragraph","content": [{"type": "text","text": "While an article is open, "},{"type": "phosphorIcon","attrs": {"iconName": "PhStar","weight": "fill","size": 16}},{"type": "text","text": " in the article header adds or removes it from favorites. Favorites are personal: other users cannot see another user's list."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Related articles"}]},{"type": "paragraph","content": [{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-000000000008","label": "kba-sy1008 — Navigate folders and articles","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1008","status": "published","articleTypeCode": "wiki"}}}]}]}}$kb_a005_en$::jsonb,
