(
    'e1c10000-0000-4000-8000-000000000005', 'russian',
    'Поиск и избранное',
    $kb_a005_ru${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Поиск"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhMagnifyingGlass","weight": "regular","size": 16}},{"type": "text","text": " в заголовке панели дерева открывает поле поиска. Ввод текста фильтрует статьи в развёрнутых базах на полке. Очистка поля или скрытие поиска сбрасывает фильтр."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Блок избранного"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhStar","weight": "regular","size": 16}},{"type": "text","text": " в заголовке панели показывает или скрывает блок «Избранное» над списком деревьев. Блок отображает все статьи, отмеченные текущим пользователем."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Добавление статьи в избранное"}]},{"type": "paragraph","content": [{"type": "text","text": "При открытой статье кнопка "},{"type": "phosphorIcon","attrs": {"iconName": "PhStar","weight": "fill","size": 16}},{"type": "text","text": " в заголовке статьи добавляет её в избранное или убирает из него. Избранное является личным: другие пользователи не видят чужой список."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Связанные статьи"}]},{"type": "paragraph","content": [{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-000000000008","label": "kba-sy1008 — Навигация по папкам","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1008","status": "published","articleTypeCode": "wiki"}}}]}]}}$kb_a005_ru$::jsonb,
