(
    'e1c10000-0000-4000-8000-000000000006', 'english',
    'KB Library: add and remove bases',
    $kb_a006_en${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Open the library"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhBooks","weight": "regular","size": 16}},{"type": "text","text": " KB Library, in the tree panel footer above "},{"type": "phosphorIcon","attrs": {"iconName": "PhFadersHorizontal","weight": "regular","size": 16}},{"type": "text","text": " Settings, opens the catalog of available knowledge bases. On first entry, an introductory screen is shown; selecting Open library dismisses it."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Add a knowledge base to the shelf"}]},{"type": "paragraph","content": [{"type": "text","text": "Each card in the library displays the name, owner, status, and short description of a knowledge base. "},{"type": "phosphorIcon","attrs": {"iconName": "PhPlus","weight": "bold","size": 16}},{"type": "text","text": " on a card adds the knowledge base to the personal shelf, shown in the left panel. "},{"type": "phosphorIcon","attrs": {"iconName": "PhCheckCircle","weight": "fill","size": 16}},{"type": "text","text": " marks knowledge bases already on the shelf."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Filters and sorting"}]},{"type": "bulletList","content": [{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "Search by name, description, or owner."}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "Filter by shelf status, tree status, or owner, including a My knowledge bases filter."}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "Sort by name, creation date, or owner."}]}]}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Remove from the shelf"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhSignOut","weight": "regular","size": 16}},{"type": "text","text": " Return to KB Library, in the tree root header, removes the knowledge base from the personal shelf only. The knowledge base itself and its content are not affected."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Related articles"}]},{"type": "paragraph","content": [{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-000000000007","label": "kba-sy1007 — Organizing the tree panel","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1007","status": "published","articleTypeCode": "wiki"}}},{"type": "text","text": "; "},{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-00000000001a","label": "kba-sy1026 — Return to library vs delete KB","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1026","status": "published","articleTypeCode": "wiki"}}}]}]}}$kb_a006_en$::jsonb,
