    'Edit mode workflow',
    $kb_a00b_en${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Enter edit mode"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhPencil","weight": "regular","size": 16}},{"type": "text","text": " in the header of a tree root, folder, or article the current user may edit opens edit mode. An actions pane with save and workflow controls appears on the right."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Save changes"}]},{"type": "bulletList","content": [{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhFloppyDisk","weight": "regular","size": 16}},{"type": "text","text": " UPDATE — saves all pending changes: title, content, tags, status, attachments, and other edited fields."}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhArrowCounterClockwise","weight": "regular","size": 16}},{"type": "text","text": " DROP CHANGES — reverts unsaved edits made in the current session."}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhSignOut","weight": "regular","size": 16}},{"type": "text","text": " CLOSE EDITOR — exits edit mode; if unsaved changes exist, a save-or-discard prompt is shown first."}]}]}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Unsaved changes indicator"}]},{"type": "paragraph","content": [{"type": "text","text": "Fields with unsaved edits are highlighted with a subtle glow. evi prompts for confirmation before discarding unsaved work when navigating away or switching modules."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Related articles"}]},{"type": "paragraph","content": [{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-00000000000c","label": "kba-sy1012 — Folders and tree structure","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1012","status": "published","articleTypeCode": "wiki"}}}]}]}}$kb_a00b_en$::jsonb,
