(
    'e1c10000-0000-4000-8000-00000000000b', 'russian',
    'Режим редактирования',
    $kb_a00b_ru${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Вход в режим редактирования"}]},{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhPencil","weight": "regular","size": 16}},{"type": "text","text": " в заголовке корня, папки или статьи, доступной текущему пользователю для редактирования, открывает режим редактирования. Справа появляется панель действий с элементами сохранения и рабочего процесса."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Сохранение изменений"}]},{"type": "bulletList","content": [{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhFloppyDisk","weight": "regular","size": 16}},{"type": "text","text": " UPDATE — сохраняет все несохранённые изменения: заголовок, контент, теги, статус, вложения и другие изменённые поля."}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhArrowCounterClockwise","weight": "regular","size": 16}},{"type": "text","text": " DROP CHANGES — отменяет правки, внесённые в текущей сессии."}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "phosphorIcon","attrs": {"iconName": "PhSignOut","weight": "regular","size": 16}},{"type": "text","text": " CLOSE EDITOR — выход из режима редактирования; при наличии несохранённых изменений сначала выводится запрос на сохранение или отмену."}]}]}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Индикатор несохранённых изменений"}]},{"type": "paragraph","content": [{"type": "text","text": "Поля с несохранёнными правками подсвечиваются лёгким свечением. При переходе на другую страницу или переключении модуля evi запрашивает подтверждение перед потерей несохранённых данных."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Связанные статьи"}]},{"type": "paragraph","content": [{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-00000000000c","label": "kba-sy1012 — Папки и структура","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1012","status": "published","articleTypeCode": "wiki"}}}]}]}}$kb_a00b_ru$::jsonb,
