    'Application settings: session management',
    $kb_a037_en${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Token management"}]},{"type": "paragraph","content": [{"type": "text","text": "evi authorizes API requests with a short-lived access token (JWT), paired with a longer-lived refresh token stored as a cookie. Session management settings, in application settings under Security → Session management, control the lifetime and rotation behavior of both:"}]},{"type": "table","content": [{"type": "tableRow","content": [{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Setting"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Range"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Description"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "access token lifetime"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "5–120 minutes, step 5"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "validity period of the access token used to authorize API requests"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "refresh N seconds before expiry"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "30–240 seconds, step 10"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "how many seconds before access-token expiry the client may request a refreshed token"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "refresh token lifetime"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–30 days"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "validity period of the refresh token"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "maximum refresh tokens per user"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–10"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "maximum number of concurrently active refresh tokens — roughly, signed-in devices — per user"}]}]}]}]},{"type": "paragraph","content": [{"type": "text","text": "Two switches control automatic invalidation of refresh tokens on password changes:"}]},{"type": "bulletList","content": [{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "drop all active refresh tokens except the current one from the user's devices when the user changes their own password"}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "drop all active refresh tokens when an administrator resets a user's password"}]}]}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "API request rate limiting"}]},{"type": "paragraph","content": [{"type": "text","text": "Connection handling settings, in the same section, protect the API from excessive request volume per user. A single switch turns rate limiting on or off entirely; when enabled, requests are grouped into four tiers, each with its own per-user limit:"}]},{"type": "table","content": [{"type": "tableRow","content": [{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Tier"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Typical use"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Range, requests/minute"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "strict"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "authentication endpoints"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–1,000"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "elevated"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "mutating requests (create, update, delete)"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–1,000"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "standard"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "read requests"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–10,000"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "relaxed"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "catalog and other high-volume read endpoints"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–100,000"}]}]}]}]},{"type": "paragraph","content": [{"type": "text","text": "When a user exceeds a tier's limit, further requests in that tier are blocked for a configurable duration, from 1 to 60 minutes."}]}]}}$kb_a037_en$::jsonb,
