    'Настройки приложения: управление сессиями',
    $kb_a037_ru${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Управление токенами"}]},{"type": "paragraph","content": [{"type": "text","text": "evi авторизует API-запросы с помощью короткоживущего токена доступа (JWT) в паре с более долгоживущим refresh-токеном, хранящимся в cookie. Настройки управления сессиями, в настройках приложения в разделе Безопасность → Управление сессиями, определяют время жизни и порядок обновления обоих токенов:"}]},{"type": "table","content": [{"type": "tableRow","content": [{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Настройка"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Диапазон"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Описание"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "время жизни токена доступа"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "5–120 минут, шаг 5"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "срок действия токена доступа, используемого для авторизации API-запросов"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "обновление за N секунд до истечения"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "30–240 секунд, шаг 10"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "за сколько секунд до истечения токена доступа клиент может запросить обновлённый токен"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "время жизни refresh-токена"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–30 дней"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "срок действия refresh-токена"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "максимум refresh-токенов на пользователя"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–10"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "максимальное число одновременно активных refresh-токенов — приблизительно, устройств с активным входом — на одного пользователя"}]}]}]}]},{"type": "paragraph","content": [{"type": "text","text": "Два переключателя управляют автоматическим аннулированием refresh-токенов при смене пароля:"}]},{"type": "bulletList","content": [{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "сбрасывать все активные refresh-токены на устройствах пользователя, кроме текущего, когда пользователь меняет собственный пароль"}]}]},{"type": "listItem","content": [{"type": "paragraph","content": [{"type": "text","text": "сбрасывать все активные refresh-токены, когда администратор сбрасывает пароль пользователя"}]}]}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Ограничение частоты API-запросов"}]},{"type": "paragraph","content": [{"type": "text","text": "Настройки обработки соединений, в том же разделе, защищают API от избыточного объёма запросов на одного пользователя. Один переключатель полностью включает или отключает ограничение частоты; при включении запросы делятся на четыре уровня, каждый со своим лимитом на пользователя:"}]},{"type": "table","content": [{"type": "tableRow","content": [{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Уровень"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Типичное использование"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Диапазон, запросов/мин"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "строгий"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "эндпоинты аутентификации"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–1000"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "повышенный"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "изменяющие запросы (создание, обновление, удаление)"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–1000"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "стандартный"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "запросы на чтение"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–10 000"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "свободный"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "каталог и другие высоконагруженные эндпоинты на чтение"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "1–100 000"}]}]}]}]},{"type": "paragraph","content": [{"type": "text","text": "При превышении лимита уровня дальнейшие запросы этого уровня блокируются на настраиваемый срок, от 1 до 60 минут."}]}]}}$kb_a037_ru$::jsonb,
