    $kb_a03a_en${"body": {"type": "doc","content": [{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Module toggles"}]},{"type": "paragraph","content": [{"type": "text","text": "The modules section, in application settings under System → Modules, controls whether each application module is available in the installation:"}]},{"type": "table","content": [{"type": "tableRow","content": [{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Module"}]}]},{"type": "tableHeader","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Setting"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Work"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "work.module.enabled"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Reports"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "reports.module.enabled"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Knowledge Base"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "knowledgebase.module.enabled"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Products"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "products.module.enabled"}]}]}]},{"type": "tableRow","content": [{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "Services"}]}]},{"type": "tableCell","attrs": {"colspan": 1,"rowspan": 1,"colwidth": null},"content": [{"type": "paragraph","content": [{"type": "text","text": "services.module.enabled"}]}]}]}]},{"type": "paragraph","content": [{"type": "text","text": "Disabling a module hides it for every user of the installation, without exception — including users who hold an administrative role within that module. The knowledge base module's own roles and settings are described separately."}]},{"type": "heading","attrs": {"level": 2},"content": [{"type": "text","text": "Related articles"}]},{"type": "paragraph","content": [{"type": "entityLink","attrs": {"entityType": "kb_article","entityId": "e1c10000-0000-4000-8000-00000000001b","label": "kba-sy1027 — KB module roles and settings","meta": {"treeId": "e1b10000-0000-4000-8000-000000000001","treeName": "HELP KB","shortId": "kba-sy1027","status": "published","articleTypeCode": "wiki"}}}]}]}}$kb_a03a_en$::jsonb,
