-- ===========================================================================
-- 15. Move default landing settings to Application.System.Modules
-- ===========================================================================

UPDATE app.app_settings
SET section_path = 'Application.System.Modules',
    updated_at = CURRENT_TIMESTAMP
WHERE section_path = 'Application.Appearance'
  AND setting_name IN (
    'default.module.anonymous.users',
    'default.module.registered.users'
  )
  AND NOT EXISTS (
    SELECT 1 FROM app.app_settings n
    WHERE n.section_path = 'Application.System.Modules'
      AND n.setting_name = app.app_settings.setting_name
      AND n.environment = app.app_settings.environment
  );

INSERT INTO app.app_settings (
  section_path, setting_name, environment, value,
  validation_schema, default_value, description, is_public
) VALUES
  ('Application.System.Modules', 'default.module.registered.users', 'all',
   '"catalog"', '{"type":"string","enum":["catalog","about","work","knowledgebase","ar"]}',
   '"catalog"', 'Default module shown to registered users on app load, page refresh, and after login.', true),
  ('Application.System.Modules', 'default.module.anonymous.users', 'all',
   '"login"', '{"type":"string","enum":["login","about"]}',
   '"login"', 'Default module shown to anonymous users on app load, page refresh, and after logout.', true)
ON CONFLICT (section_path, setting_name, environment) DO UPDATE SET
  validation_schema = EXCLUDED.validation_schema,
  default_value = EXCLUDED.default_value,
  description = EXCLUDED.description,
  is_public = EXCLUDED.is_public,
  updated_at = CURRENT_TIMESTAMP;

DELETE FROM app.app_settings
WHERE section_path = 'Application.Appearance'
  AND setting_name IN (
    'default.module.anonymous.users',
    'default.module.registered.users'
  );

