-- ===========================================================================
-- 17. Catalog-visibility: new service enums
-- ===========================================================================

DO $$ BEGIN
    CREATE TYPE app.service_operational_status AS ENUM (
        'available', 'planned_maintenance', 'emergency_maintenance', 'paused'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

COMMENT ON TYPE app.service_operational_status IS 'Operational state of a catalog service: available, planned_maintenance, emergency_maintenance, paused.';

DO $$ BEGIN
    CREATE TYPE app.service_pause_reason AS ENUM (
        'business', 'security', 'other'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

COMMENT ON TYPE app.service_pause_reason IS 'Reason a service is paused: business, security, or other. Required only when operational_status is paused.';

-- ===========================================================================
-- 18. Catalog-visibility: app.services — new columns last (matches golden-master CREATE TABLE)
-- ===========================================================================

ALTER TABLE app.services
    ADD COLUMN IF NOT EXISTS operational_status app.service_operational_status NOT NULL DEFAULT 'available'::app.service_operational_status;

ALTER TABLE app.services
    ADD COLUMN IF NOT EXISTS pause_reason app.service_pause_reason;

ALTER TABLE app.services
    ADD COLUMN IF NOT EXISTS catalog_visible BOOLEAN NOT NULL DEFAULT false;

-- Backfill from the old identity status before that column is dropped.
-- Pilot rewrite is acceptable; the mapping still runs if any rows exist.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'app'
          AND table_name = 'services'
          AND column_name = 'status'
    ) THEN
        UPDATE app.services
        SET
            catalog_visible = (status = 'active'::app.service_status),
            operational_status = CASE status
                WHEN 'under_maintenance'::app.service_status
                    THEN 'planned_maintenance'::app.service_operational_status
                WHEN 'suspended'::app.service_status
                    THEN 'paused'::app.service_operational_status
                ELSE 'available'::app.service_operational_status
            END,
            pause_reason = CASE
                WHEN status = 'suspended'::app.service_status
                    THEN 'other'::app.service_pause_reason
                ELSE NULL
            END;
    END IF;
END $$;

DO $$
BEGIN
    ALTER TABLE app.services
        ADD CONSTRAINT chk_services_pause_reason CHECK (
            (operational_status = 'paused'::app.service_operational_status AND pause_reason IS NOT NULL)
            OR (operational_status <> 'paused'::app.service_operational_status AND pause_reason IS NULL)
        );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

COMMENT ON COLUMN app.services.operational_status IS 'Operational state shown to consumers: available, planned_maintenance, emergency_maintenance, or paused. Independent of catalog_visible.';
COMMENT ON COLUMN app.services.pause_reason IS 'Required when operational_status is paused; must be NULL otherwise (chk_services_pause_reason). Values: business, security, other.';
COMMENT ON COLUMN app.services.catalog_visible IS 'Admin toggle to show the service in the catalog. Independent of operational_status. Default false.';

ALTER TABLE app.services DROP COLUMN IF EXISTS status;
ALTER TABLE app.services DROP COLUMN IF EXISTS service_type;
ALTER TABLE app.services DROP COLUMN IF EXISTS priority;

DROP TYPE IF EXISTS app.service_status;
DROP TYPE IF EXISTS app.service_type;
DROP TYPE IF EXISTS app.service_priority;

-- ===========================================================================
-- 19. Catalog-visibility: app.section_services — many sections per service + grid order
-- ===========================================================================

ALTER TABLE app.section_services DROP CONSTRAINT IF EXISTS uq_section_services_service;

ALTER TABLE app.section_services
    ADD COLUMN IF NOT EXISTS "order" INTEGER NOT NULL DEFAULT 0;

COMMENT ON TABLE app.section_services IS 'Service placements in catalog sections. A service may be in N sections; "order" is the grid position within a section.';
COMMENT ON COLUMN app.section_services.section_id IS 'Reference to catalog section';
COMMENT ON COLUMN app.section_services.service_id IS 'Reference to service';
COMMENT ON COLUMN app.section_services."order" IS 'Grid position of the service card within the catalog section.';

-- ===========================================================================
-- 20. Catalog-visibility: work_item_forms — drop identity status; catalog_visible default false
-- ===========================================================================

ALTER TABLE app.work_item_forms DROP CONSTRAINT IF EXISTS chk_work_item_forms_active_has_version;
ALTER TABLE app.work_item_forms DROP COLUMN IF EXISTS status;
DROP TYPE IF EXISTS app.work_item_form_status;

ALTER TABLE app.work_item_forms
    ALTER COLUMN catalog_visible SET DEFAULT false;

-- ===========================================================================
-- 21. Catalog-visibility: form-version status published → active (idempotent)
-- ===========================================================================

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM pg_enum e
        JOIN pg_type t ON t.oid = e.enumtypid
        JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE n.nspname = 'app'
          AND t.typname = 'work_item_form_version_status'
          AND e.enumlabel = 'published'
    ) THEN
        ALTER TYPE app.work_item_form_version_status RENAME VALUE 'published' TO 'active';
    END IF;
END $$;

COMMENT ON TYPE app.work_item_form_version_status IS 'Lifecycle of one form version. Active versions are frozen; retired versions keep serving stamped work items that already reference them.';

COMMENT ON COLUMN app.work_item_forms.catalog_visible IS 'Toggle to show the consumer the live/active version; does not change versioning or the service binding. Default false.';
COMMENT ON COLUMN app.work_item_forms.current_version_id IS 'Active version new work items start from. NULL while the form has only drafts.';
COMMENT ON TABLE app.work_item_form_versions IS 'Immutable snapshot of a work item form body. Active versions are frozen; retired ones keep serving stamped work items that already reference them.';
COMMENT ON COLUMN app.work_item_form_versions.published_at IS 'Set when the version becomes active; from then on the row is frozen except status/change_note/audit columns.';

-- current_version_id must point at an active version of the same form.
CREATE OR REPLACE FUNCTION app.tgr_work_item_forms_validate_current_version()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_form_id UUID;
    v_status      app.work_item_form_version_status;
BEGIN
    IF NEW.current_version_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT form_id, status
    INTO v_form_id, v_status
    FROM app.work_item_form_versions
    WHERE id = NEW.current_version_id;

    IF v_form_id IS NULL THEN
        RAISE EXCEPTION 'work item form %: current version % not found', NEW.id, NEW.current_version_id
            USING ERRCODE = '23503';
    END IF;

    IF v_form_id IS DISTINCT FROM NEW.id THEN
        RAISE EXCEPTION 'work item form %: current version % belongs to another form', NEW.id, NEW.current_version_id
            USING ERRCODE = '23514';
    END IF;

    IF v_status <> 'active'::app.work_item_form_version_status THEN
        RAISE EXCEPTION 'work item form %: current version % must be active (is %)', NEW.id, NEW.current_version_id, v_status
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

-- ===========================================================================
-- 22. Catalog-visibility: form indexes — drop status-based, add visibility-based
-- ===========================================================================

DROP INDEX IF EXISTS app.idx_work_item_forms_kind_status;
DROP INDEX IF EXISTS app.idx_work_item_forms_service_status_order;

CREATE INDEX IF NOT EXISTS idx_work_item_forms_kind
    ON app.work_item_forms USING btree (work_item_kind);

CREATE INDEX IF NOT EXISTS idx_work_item_forms_service_visible_order
    ON app.work_item_forms USING btree (service_id, catalog_visible, catalog_order);

-- ===========================================================================
-- 23. work_item_forms.catalog_order — comment + per-service 1..N backfill
-- ===========================================================================

COMMENT ON COLUMN app.work_item_forms.catalog_order IS 'Position within the service''s catalog grid. 1-based when bound; 0 when unbound.';

WITH ranked AS (
    SELECT id,
           row_number() OVER (
               PARTITION BY service_id
               ORDER BY catalog_order, created_at, id
           ) AS rn
    FROM app.work_item_forms
    WHERE service_id IS NOT NULL
)
UPDATE app.work_item_forms f
SET catalog_order = ranked.rn
FROM ranked
WHERE f.id = ranked.id;

-- ===========================================================================
-- 24. Version stamp
-- ===========================================================================

DO $$
BEGIN
    PERFORM app.set_migration_output_summary(
        'm_0.23.8',
        'Split approval from work-item status (new app.work_item_approval_status / app.work_item_status; pending_approval+approved -> in_progress, rejected -> closed) and renamed service-request SQL objects to the work_item_ convention: table work_item_service_requests, five shared enums, sequence, indexes, triggers, functions and constraints. Also added app.kb_trees/kb_nodes/kb_articles.content_version (BIGINT NOT NULL DEFAULT 1) and content_hash (VARCHAR(80), nullable) — generic per-entity content revision stamp, independent of system_content_version/hash. Also synced the built-in HELP KB tree content from db/kb-system/users.sql (v1.17.0) so every kb_trees/kb_nodes/kb_articles row carries content_version=1 and content_hash (infrastructure only; no documentation text changed). Moved default.module.anonymous.users and default.module.registered.users from Application.Appearance to Application.System.Modules (value preserved). Application.Appearance theme.mode factory default is now system (existing value preserved). Catalog-visibility parity: services gained operational_status / pause_reason / catalog_visible (backfilled from status) and dropped status / service_type / priority; section_services allows a service in N sections with grid "order"; forms dropped identity status, catalog_visible defaults to false, form-version published was renamed to active. No data loss beyond the status remap and catalog-visibility mapping described above. Restated work_item_forms.catalog_order COMMENT (1-based when bound; 0 when unbound) and backfilled bound rows to a contiguous per-service 1..N sequence.'
    );
END $$;

UPDATE app.instance
SET schema_version = '0.23.8', last_updated_at = NOW()
WHERE id = 1;

COMMIT;
